import{_ as t,o as e,c as o,a4 as a}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-123","description":"","frontmatter":{"date":"2022-01-01T21:04:05","title":"写作课作业-123","categories":["写作","作业","薄世宁医学通识"],"tags":["写作","作业","薄世宁医学通识"]},"headers":[],"relativePath":"posts/homework/123.md","filePath":"posts/homework/123.md"}'),s={name:"posts/homework/123.md"};function r(c,p,_,l,n,i){return e(),o("div",null,[...p[0]||(p[0]=[a("<p>今天抽时间总算把《薄世宁医学通识讲义》读完。书中的一些医疗的发展历史，在《医学大神》这套书中有所讲解，推荐看看，既能了解历史而且故事性很强很容易读。对医疗过程，医疗结果和医疗意义的部分补充，如果自己还在从事医疗信息化的开发应该是有帮助的，于是推荐给了之前的同事，希望他也看看。</p><p>看到第七章的时候，讲的是医生的精进之路，其实在生活中也挺适用的。</p><p>下面是摘抄的医生精进之路的三关：</p><blockquote><p>第一关，少即是多。</p><p>做到“少即是多”的三个方法，第一，寻找杠杆解；第二，在效益相似的情况下，寻找代价最小的解决方案。第三，终局思维。</p></blockquote><p>书中的例子是1870年9月6日，沉没的英国皇家海军铁甲舰“船长”号——越复杂，越多隐患。其实Linux的哲学是KISS（Keep It Simple &amp; Stupid）原则，也是在引导设计人员克制。奥卡姆剃刀定律“如无必要，勿增实体”说的也是这事。虽然有种种的原则，然而我们看到有些系统设计中就是搞得很复杂，只有复杂才显得自己厉害。当Go以“少即是多”为设计理念的时候，并且十年过去了，他还一直坚持着这份理念，选择就容易做出了。</p><p>寻找代价最小的解决方案，这个和我们做系统架构时的平衡是一个道理，在性能和稳定性，安全和成本，时间和质量间做好平衡。</p><p>关于“终局思维”，更多的说法可能是“以终为始”，在郑烨的《10x程序员工作法》中也提及了，倒着想，不仅能帮着规划工作，还能发现问题。</p><blockquote><p>第二关，在信息不完备的情况下快速决策。</p><p>在思维逻辑方面，医生在信息不完备的情况下做决策，会遵守四条法则，第一，唐僧法则（先保证活着）；第二，第一张骨牌法则；第三，马蹄声法则；第四，高尔夫法则。</p><p>在医学的复杂性面前，</p><p>灵活带来的优势越来越小，</p><p>原则带来的优势越来越大。</p></blockquote><p>其实文章的前面一段“如果找不到无序的理由，那就先用规则去恢复有序”，这一段是对当时伍连德，防控中国肺鼠疫的一个小节。</p><p>还有更早章节中的一段：</p><blockquote><p>临床工作为什么需要指南？</p><p>第一，指南可以减少医生水平差异带来的治疗结果差异。</p><p>第二，遵守只能可以保障治疗效果，降低风险。</p></blockquote><p>回到我们的开发设计中来，为什么需要引入某些框架，某些规范，其实引入的是约束，在这些约束下，我们能降低不同人员的水平差异，能减少人工出错的可能，让系统更加稳定。</p><p>第一张骨牌法则，其实和我们系统中处理的死锁有类似的地方，如果切断其中一个锁，后续的系统就可以恢复正常了。其实我们回顾“氯丙嗪：精神病治疗的第一道曙光”，如果能找到发病的某个因果链条，阻断这个链条，同样可以治病。我们修复系统BUG时，常常引用了第三方的组件，在第三方没有办法修改的情况下，我们来修改，其实也是打断了链条。有时我们可以把公司的组织结构看成另一种形态的架构，在一些职责未分或者分得过于清晰的地方，自己多做一点点，打破某个链条，一种新的可能也就出现了。</p><blockquote><p>第三关，克服不理性的冲动</p><p>非理性和理性是人类思维中固有的两个方面，医生做决策时的思维同样符合这两个思维模式。医生的“士兵思维”就是把所有符合他直觉的诊断信息当成自己的战友保护起来，把不符合他判断的信息当成敌人过滤掉、消灭掉。而医生的“侦察兵思维”就是摒除内心的歧视、偏见和强烈的倾向，尽可能客观地找出所有有价值的证据。</p></blockquote><p>作为技术人员，经常为因为实现的复杂度，性能等问题窄化自己的思维，有时甚至因为自己的不理智和产品与需求产生不愉快，但如果我们能站在“侦察兵思维”触发，我们从客户的真实需求，站在公司产品更加人性化，提升产品质量的角度，能否进一步梳理需求，共同想到更优的解决方案呢。</p><p>其实，看看“马蹄声法则”、“高尔夫法则”和“侦察兵思维”其实是独立思考，不能因为直觉，偏见，情绪而忽略事实。</p><p>知道和做到，有一条巨大的鸿沟，就算读过《批判性思维》，自己也经常在逻辑上犯错误。</p>",17)])])}const d=t(s,[["render",r]]);export{m as __pageData,d as default};
